130	            Simple_fcn mkArr = Glue.instantiateGenericConstructor(Driver.getFortressLibrary(),
131	                                                                  WellKnownNames.varargsFactoryName,
132	                                                                  stringType,
133	                                                                  natParams);
134	            FValue result = mkArr.applyToArgs();
135	            if (!(result instanceof PrimImmutableArray.PrimImmutableArrayObject)) {
136	                return bug("registerProgramArgs: unexpected varargs array type " + result);
137	            }
138	            PrimImmutableArray.PrimImmutableArrayObject arr = (PrimImmutableArray.PrimImmutableArrayObject) result;
139	            for (int i = 0; i < args.size(); i++) {
140	                arr.init(i, FString.make(args.get(i)));
