145	        protected FValue applyToArgs() {
146	            if (convertedArgs == null) {
147	                if (args == null) {
148	                    return bug("No program args were registered by calling " +
149	                               "StringPrim.GetProgramArgs.registerProgramArgs");
150	                }
151	                synchronized (args) {
152	                    if (convertedArgs == null) {
153	                        convertedArgs = grindProgramArgs();
154	                    }
155	                }
156	            }
157	            return convertedArgs;
